def value(name, default=None):
    """NAME from the environment, else from the project's settings files, else DEFAULT."""
    if os.environ.get(name):
        return os.environ[name]
    for root in roots():
        for file in FILES:
            try:
                found = json.loads((root / ".claude" / file).read_text()).get("env", {}).get(name)
            except (OSError, ValueError, AttributeError):
                continue
            if isinstance(found, str) and found:
                return found
    return default

